package family.khaira.supersetcompanion.core

/**
 * What the phone believes about its route to the desktop.
 *
 * The distinctions here are not cosmetic — they were confirmed against the real
 * Cloudflare tunnel before any client code existed, and they decide what the user is
 * told to do. Getting them wrong sends someone to go poke a machine that was fine.
 *
 *  530 — the tunnel is not connected. `cloudflared` runs as a Windows service
 *        independent of Superset, so this means the desktop itself is asleep or off.
 *  502 — the tunnel is up and reached the machine, but nothing is listening on the
 *        bridge port. The desktop is awake; Superset is not running.
 *  403 / redirect to the team login page — blocked at Cloudflare Access. A credential
 *        problem, not a desktop problem.
 *  200 — the bridge answered.
 */
sealed interface ConnectionState {
    /** The bridge answered. */
    data object Online : ConnectionState

    /** 530: tunnel down. The desktop is asleep or powered off. */
    data object DesktopUnreachable : ConnectionState

    /** 502: tunnel up, bridge absent. Superset is closed. */
    data object SupersetNotRunning : ConnectionState

    /** Rejected at the edge — service token missing, wrong, or revoked. */
    data class AccessDenied(val detail: String) : ConnectionState

    /** No usable network on this device. */
    data object Offline : ConnectionState

    /** Reached something, but it was not a shape we understand. */
    data class Unexpected(val status: Int, val detail: String) : ConnectionState
}

