package family.khaira.supersetcompanion.wear.datalayer

import com.google.android.gms.wearable.MessageEvent
import com.google.android.gms.wearable.WearableListenerService

/**
 * The watch's only route to anything. It has no independent path to the desktop, so
 * every question and every answer travels through the phone over the Data Layer.
 *
 * This silently delivers nothing if app-watch and app-phone differ in applicationId or
 * signing key — no error, no callback. Both are pinned in the two build files.
 */
class CompanionWearListenerService : WearableListenerService() {
    override fun onMessageReceived(event: MessageEvent) {
        // TODO: question delivery, answer acknowledgement, lease refusal.
    }
}

