/**
 * tmp/ only. Minimal better-sqlite3 stand-in so the companion bridge can be
 * BOOTED on a machine where the workspace was never fully installed (root
 * node_modules holds 7 dev tools; packages/host-service/node_modules/
 * better-sqlite3 is an empty directory with no compiled .node binding).
 *
 * This is NOT a database. Every query returns empty. It exists to answer one
 * question the whole project has never answered — does start() complete and
 * does the listener reject hostile input safely — without a full install and
 * a win-arm64 native build.
 *
 * Anything that depends on real rows (the agent tree, transcripts) will look
 * empty, and that is stated in the harness output rather than hidden.
 */

class Statement {
	constructor(readonly sql: string) {}
	all(): unknown[] {
		return [];
	}
	get(): undefined {
		return undefined;
	}
	run(): { changes: number; lastInsertRowid: number } {
		return { changes: 0, lastInsertRowid: 0 };
	}
	iterate(): IterableIterator<unknown> {
		return [][Symbol.iterator]();
	}
	pluck(): this {
		return this;
	}
	raw(): this {
		return this;
	}
	bind(): this {
		return this;
	}
}

export default class Database {
	open = true;
	constructor(
		readonly name: string,
		readonly options?: unknown,
	) {}
	prepare(sql: string): Statement {
		return new Statement(sql);
	}
	exec(): this {
		return this;
	}
	pragma(): unknown[] {
		return [];
	}
	transaction<T extends (...args: never[]) => unknown>(fn: T): T {
		return fn;
	}
	close(): this {
		this.open = false;
		return this;
	}
	function(): this {
		return this;
	}
	aggregate(): this {
		return this;
	}
	loadExtension(): this {
		return this;
	}
}

