/**
 * Standalone bridge boot harness.  tmp/ only — not repo source.
 *
 * The companion bridge has never been started. Everything so far is "it
 * compiles and the gates are green". This boots it against a THROWAWAY host.db
 * so the user's running Superset is never touched, then drives the cleartext
 * health path and the unauthenticated rejection paths.
 *
 * It does not pair, does not seal a request, and never writes to a terminal.
 */
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, rmSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { createDb } from "../packages/host-service/src/db";
import {
	SqliteTerminalAgentBindingPersistence,
	TerminalAgentStore,
} from "../packages/host-service/src/terminal-agents";
import { startCompanionBridgeIfEnabled } from "../packages/host-service/src/companion";

const REPO = join(import.meta.dirname, "..");
const scratch = mkdtempSync(join(tmpdir(), "companion-boot-"));

// The bridge reads its real config from ~/.superset/companion. Point HOME-derived
// paths at a scratch dir so nothing here can disturb the real device keys.
process.env.SUPERSET_COMPANION_BRIDGE = "1";
process.env.SUPERSET_HOME_DIR = scratch;

let bridge: Awaited<ReturnType<typeof startCompanionBridgeIfEnabled>> = null;

async function probe(label: string, url: string, init?: RequestInit) {
	try {
		const res = await fetch(url, init);
		const body = await res.text();
		console.log(
			`  ${label.padEnd(34)} ${res.status} ${body.slice(0, 110).replace(/\s+/g, " ")}`,
		);
	} catch (error) {
		console.log(`  ${label.padEnd(34)} FETCH-FAILED ${(error as Error).message}`);
	}
}

async function main() {
	const dbPath = join(scratch, "host.db");
	console.log(`scratch: ${scratch}`);

	// Copy ONLY the two credential files the bridge requires into the scratch
	// tree. Everything the bridge then writes — the state anchor, the send
	// witness, devices.json — lands in scratch and dies with it, so a boot test
	// can never disturb the real device keys under ~/.superset/companion.
	const realDir = join(homedir(), ".superset", "companion");
	mkdirSync(join(scratch, "companion"), { recursive: true });
	for (const f of ["cloudflare-access.json", "fcm-service-account.json"]) {
		const src = join(realDir, f);
		if (!existsSync(src)) {
			console.log(`MISSING real config: ${src} — cannot boot`);
			return;
		}
		copyFileSync(src, join(scratch, "companion", f));
	}
	console.log("real credentials copied into scratch (originals untouched)");

	const db = createDb(dbPath, join(REPO, "packages/host-service/drizzle"));
	const terminalAgentStore = new TerminalAgentStore(
		new SqliteTerminalAgentBindingPersistence(db),
	);
	console.log("db + agent store constructed");

	const started = Date.now();
	bridge = await startCompanionBridgeIfEnabled({
		hostDbPath: dbPath,
		db,
		terminalAgentStore,
	});
	console.log(
		bridge === null
			? "BRIDGE IS NULL — start() threw and was swallowed; see the error above"
			: `BRIDGE STARTED in ${Date.now() - started}ms`,
	);
	if (bridge === null) return;

	const base = "http://127.0.0.1:47610";
	console.log("\n--- unauthenticated probes ---");
	await probe("GET /v1/ping", `${base}/v1/ping`);
	await probe("GET / (unknown path)", `${base}/`);
	await probe("GET /v1/tree (needs seal)", `${base}/v1/tree`);
	await probe("POST /v1/answer garbage", `${base}/v1/answer`, {
		method: "POST",
		body: "not-a-sealed-envelope",
	});
	await probe("POST /v1/answer 4MB body", `${base}/v1/answer`, {
		method: "POST",
		body: "A".repeat(4 * 1024 * 1024),
	});
	await probe("POST /v1/answer empty", `${base}/v1/answer`, { method: "POST" });

	console.log("\n--- is it still alive after that? ---");
	await probe("GET /v1/ping (again)", `${base}/v1/ping`);
}

main()
	.catch((error) => {
		console.error("\nHARNESS FAILED:");
		console.error(error);
		process.exitCode = 1;
	})
	.finally(async () => {
		if (bridge !== null) {
			await bridge.stop("harness").catch(() => {});
			console.log("\nbridge stopped cleanly");
		}
		rmSync(scratch, { recursive: true, force: true });
	});

// tmp/ only. Redirects the bare specifier "better-sqlite3" to the local stub so
// the bridge can boot without a compiled native binding. Used via --preload.
import { plugin } from "bun";
import { join } from "node:path";

const STUB = join(import.meta.dirname, "stub-better-sqlite3.ts");

plugin({
	name: "stub-better-sqlite3",
	setup(build) {
		build.onResolve({ filter: /^better-sqlite3$/ }, () => ({ path: STUB }));
	},
});

/**
 * tmp/ only. Minimal better-sqlite3 stand-in so the companion bridge can be
 * BOOTED on a machine where the workspace was never fully installed (root
 * node_modules holds 7 dev tools; packages/host-service/node_modules/
 * better-sqlite3 is an empty directory with no compiled .node binding).
 *
 * This is NOT a database. Every query returns empty. It exists to answer one
 * question the whole project has never answered — does start() complete and
 * does the listener reject hostile input safely — without a full install and
 * a win-arm64 native build.
 *
 * Anything that depends on real rows (the agent tree, transcripts) will look
 * empty, and that is stated in the harness output rather than hidden.
 */

class Statement {
	constructor(readonly sql: string) {}
	all(): unknown[] {
		return [];
	}
	get(): undefined {
		return undefined;
	}
	run(): { changes: number; lastInsertRowid: number } {
		return { changes: 0, lastInsertRowid: 0 };
	}
	iterate(): IterableIterator<unknown> {
		return [][Symbol.iterator]();
	}
	pluck(): this {
		return this;
	}
	raw(): this {
		return this;
	}
	bind(): this {
		return this;
	}
}

export default class Database {
	open = true;
	constructor(
		readonly name: string,
		readonly options?: unknown,
	) {}
	prepare(sql: string): Statement {
		return new Statement(sql);
	}
	exec(): this {
		return this;
	}
	pragma(): unknown[] {
		return [];
	}
	transaction<T extends (...args: never[]) => unknown>(fn: T): T {
		return fn;
	}
	close(): this {
		this.open = false;
		return this;
	}
	function(): this {
		return this;
	}
	aggregate(): this {
		return this;
	}
	loadExtension(): this {
		return this;
	}
}

