// ---------------------------------------------------------------------------
// 5. PRE-WITNESS FILE (no seq, no witness) -> degrades, records still served
//
// WAS: "believed exactly once", asserting `degraded().length === 0` and a
// reach-back to `t0`. A Fable review killed that: the OLD build can lose a
// rename exactly the same way (win32 cannot force a directory entry), which
// reverts the file while its `coverageSinceMs` stays put, and nothing about a
// seq-0 file can rule that out — so believing it published an unprovable window
// and could report a landed answer as the terminal "it was not sent". The
// upgrade now costs its pre-restart coverage once, which is what every build
// before the witness did anyway.
// ---------------------------------------------------------------------------
{
	const d = await freshDir();
	// Exactly what the previous build wrote: version 1, no `seq`, no witness.
	await writeFile(
		filePath(d),
		`${JSON.stringify(
			{ version: 1, coverageSinceMs: t0, records: [confirmed] },
			null,
			"\t",
		)}\n`,
		"utf8",
	);
	const c = collector();
	const restartMs = t0 + HOUR;
	const s = await createAttemptStore({
		dir: d,
		generation: GEN_A,
		nowMs: restartMs,
		log: c.log,
	});
	check(
		"5a legacy unwitnessed file is NOT trusted: coverage degrades to this mount",
		c.degraded().length === 1 &&
			s.recordsSinceMs(restartMs) === restartMs &&
			s.recordsSinceMs(restartMs) !== t0,
		`recordsSinceMs=${s.recordsSinceMs(restartMs)} mount=${restartMs} degraded=${JSON.stringify(c.degraded())}`,
	);
	check(
		"5a2 and the degrade names the missing MARK, not a deleted witness",
		c.degraded()[0]?.why?.includes("no rewrite mark"),
		`why=${JSON.stringify(c.degraded()[0]?.why)}`,
	);
	check(
		"5a3 the record itself is still SERVED — only the window narrowed",
		s.get(base.requestId)?.status === "confirmed",
		`status=${s.get(base.requestId)?.status}`,
	);
	const file = await readJson(filePath(d));
	const wit = await readJson(witPath(d));
	check(
		"5b and it is witnessed from this mount onwards",
		file.seq === 1 && wit.seq === 1 && wit.generation === GEN_A,
		`file.seq=${file.seq} witness=${JSON.stringify(wit)}`,
	);
	check(
		"5c the gap is baked in, so the next clean mount does not re-degrade",
		file.coverageSinceMs === restartMs,
		`coverageSinceMs=${file.coverageSinceMs} mount=${restartMs}`,
	);
}

// ---------------------------------------------------------------------------
// 5d. FRESH INSTALL (no file at all) -> claims nothing, so stays SILENT
//
// The degrade test keys on whether the stamp reaches back, so an install with
// nothing to reach back into must not log a fault that did not happen.
// ---------------------------------------------------------------------------
{
	const d = await freshDir();
	const c = collector();
	const s = await createAttemptStore({
		dir: d,
		generation: GEN_A,
		nowMs: t0,
		log: c.log,
	});
	check(
		"5d fresh install: no file, no reach-back claimed, no degrade logged",
		c.degraded().length === 0 && s.recordsSinceMs(t0) === t0,
		`recordsSinceMs=${s.recordsSinceMs(t0)} mount=${t0} degraded=${JSON.stringify(c.degraded())}`,
	);
}

